{"function":"async () => {
// collect focusable sequence using deep traversal tabindex>=0 order approximation
const res=[];
const walk=(root)=>{root.querySelectorAll('*').forEach(e=>{ if(e.shadowRoot) walk(e.shadowRoot); const t=e.tabIndex; const focusable = (t>=0) && !e.disabled && (e.offsetParent!==null || getComputedStyle(e).position==='fixed'); if(focusable && (e.matches('a[href],button,input,select,textarea,[tabindex]'))) res.push(e);});};
walk(document);
return res.map(e=>{const r=e.getBoundingClientRect(); return e.tagName+(e.id?'#'+e.id:'')+'.'+(e.className||'').toString().slice(0,30)+' "'+(e.textContent||'').trim().slice(0,20)+'" '+Math.round(r.x)+','+Math.round(r.y)+' '+Math.round(r.width)+'x'+Math.round(r.height)+' ti='+e.getAttribute('tabindex')});
}"}

