{"function":"() => {
const lum=c=>{const m=c.match(/[\d.]+/g).map(Number);const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(m[0])+0.7152*f(m[1])+0.0722*f(m[2]);};
const bgOf=e=>{while(e){const b=getComputedStyle(e).backgroundColor; if(b!=='rgba(0, 0, 0, 0)'&&!b.endsWith(', 0)')) return b; e=e.parentElement||e.getRootNode().host;} return 'rgb(255,255,255)';};
const cr=(e)=>{const c=getComputedStyle(e).color, b=bgOf(e); const L1=lum(c),L2=lum(b); return {c,b,fs:getComputedStyle(e).fontSize,fw:getComputedStyle(e).fontWeight,ratio:((Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05)).toFixed(2)};};
const bc=document.querySelector('br-breadcrumb').shadowRoot.querySelector('[data-active] span');
const upd=[...document.querySelectorAll('main div.mb-2')].find(d=>d.textContent.includes('Última'));
const tabs=[...document.querySelectorAll('.tab-item button')];
const td=document.querySelector('main tbody td:nth-child(3)');
const si=document.querySelector('#search').shadowRoot?document.querySelector('#search').shadowRoot.querySelector('input'):null;
const ph=si? getComputedStyle(si,'::placeholder').color:null;
const dataLbl=[...document.querySelectorAll('main span.text-bold')].find(s=>s.textContent.includes('Data da'));
const info=document.querySelector('.pagination-information');
return {bc:cr(bc), upd:cr(upd), tabs:tabs.map(cr), td:cr(td), ph, phBg: si? getComputedStyle(si).backgroundColor:null, dataLbl:cr(dataLbl), info:cr(info), head: cr(document.querySelector('br-header').shadowRoot.querySelector('.header-sign'))};
}"}

